var importableResources = map[string]bool{
	"issues": true,
}

func unsupportedImportError(resource string) error {
	return fmt.Errorf(
		"cannot import %q: Linear has no REST create endpoint and this resource has no GraphQL import adapter; "+
			"use the typed command 'linear-pp-cli %s create' if available",
		resource,
		resource,
	)
}

func issueRecordToInput(record map[string]any) (map[string]any, error) {
	title, ok := record["title"].(string)
	if !ok || strings.TrimSpace(title) == "" {
		return nil, fmt.Errorf(`missing required field "title"`)
	}

	team, hasTeamID := record["teamId"]
	if !hasTeamID {
		team, ok = record["team"]
	}
	teamRef, ok := team.(string)
	if !ok || strings.TrimSpace(teamRef) == "" {
		return nil, fmt.Errorf(`missing required field "team" or "teamId"`)
	}

	input := make(map[string]any, len(record))
	for key, value := range record {
		input[key] = value
	}
	if _, hasTeamID := input["teamId"]; !hasTeamID {
		if team, ok := input["team"]; ok {
			input["teamId"] = team
		}
	}
	delete(input, "team")
	return input, nil
}

type importSummary struct {
	Succeeded int
	Failed    int
	Skipped   int
}

func importIssues(reader io.Reader, c *client.Client, db *store.Store, session string, dryRun, showCreated bool, stderr io.Writer) (importSummary, error) {
	scanner := bufio.NewScanner(reader)
	scanner.Buffer(make([]byte, 1024*1024), 1024*1024)

	var summary importSummary
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || line[0] == '#' {
			summary.Skipped++
			continue
		}

		var record map[string]any
		if err := json.Unmarshal([]byte(line), &record); err != nil {
			fmt.Fprintf(stderr, "warning: skipping invalid JSON line: %v\n", err)
			summary.Failed++
			continue
		}

		input, err := issueRecordToInput(record)
		if err != nil {
			fmt.Fprintf(stderr, "warning: failed to import record: %v\n", err)
			summary.Failed++
			continue
		}
		if dryRun {
			resolvedInput, err := resolveIssueTeamInput(c, db, input)
			if err != nil {
				fmt.Fprintf(stderr, "warning: failed to import record: %v\n", err)
				summary.Failed++
				continue
			}
			title, _ := resolvedInput["title"].(string)
			teamID, _ := resolvedInput["teamId"].(string)
			fmt.Fprintf(stderr, "would create issue: title=%q team=%q\n", title, teamID)
			summary.Succeeded++
			continue
		}

		issue, err := createIssueFromInput(c, db, input, session)
		if err != nil {
			fmt.Fprintf(stderr, "warning: failed to import record: %v\n", err)
			summary.Failed++
			continue
		}
		summary.Succeeded++
		if showCreated {
			fmt.Fprintf(stderr, "created %s — %s\n", issue.Identifier, issue.Title)
		}
	}
	if err := scanner.Err(); err != nil {
		return summary, fmt.Errorf("reading input: %w", err)
	}
	return summary, nil
}

func newImportCmd(flags *rootFlags) *cobra.Command {
	var inputFile string
	var batchSize int
	var dbPath string
	var session string

	cmd := &cobra.Command{
		Use:   "import <resource>",
		Short: "Bulk-create issues from a JSONL file via the issueCreate mutation",
		Long: `Bulk-create Linear issues from a JSONL file. Each line is a JSON object with
the same input fields accepted by Linear's issueCreate mutation. A "team" field
is accepted as an alias for "teamId", and team keys are resolved before create.
Each created issue is recorded in the local pp_created ledger.

Only issues are importable. Linear has no REST create endpoint, so resources
without a GraphQL import adapter must use their typed create command. Blank
lines and lines beginning with '#' are skipped. Failed records are logged and
counted without stopping later records.`,
		Example: `  # Bulk-create issues from a JSONL file
  linear-pp-cli import issues --input issues.jsonl

  # Dry-run to preview without sending
  linear-pp-cli import issues --input issues.jsonl --dry-run

  # Import from stdin
  cat issues.jsonl | linear-pp-cli import issues --input -`,
		Args: cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			resource := args[0]
			if !importableResources[resource] {
				return unsupportedImportError(resource)
			}

			if flags.trustMode == "strict" && !flags.dryRun && resolvePPSession(flags, session) == "" {
				return fmt.Errorf("trust-mode=strict: pass --session <tag> (or set PP_SESSION env) so imported fixtures are recoverable by pp-cleanup")
			}

			var reader io.Reader
			if inputFile == "-" || inputFile == "" {
				reader = cmd.InOrStdin()
			} else {
				f, err := os.Open(inputFile)
				if err != nil {
					return fmt.Errorf("opening input file: %w", err)
				}
				defer f.Close()
				reader = f
			}

			if dbPath == "" {
				dbPath = defaultDBPath("linear-pp-cli")
			}
			var db *store.Store
			opened, dbErr := store.Open(dbPath)
			if dbErr != nil {
				if !flags.dryRun {
					fmt.Fprintf(os.Stderr, "warning: cannot open ledger at %s: %v (importing without local write-back)\n", dbPath, dbErr)
				}
			} else {
				db = opened
				defer db.Close()
			}

			var c *client.Client
			createdClient, clientErr := flags.newClient()
			if clientErr != nil {
				if !flags.dryRun {
					return clientErr
				}
			} else {
				c = createdClient
			}
			sess := resolvePPSession(flags, session)

			summary, err := importIssues(reader, c, db, sess, flags.dryRun, !flags.asJSON, os.Stderr)
			if err != nil {
				return err
			}

			// JSON envelope: {succeeded, failed, skipped, dry_run}.
			if flags.asJSON {
				return printJSONFiltered(cmd.OutOrStdout(), map[string]any{
					"succeeded": summary.Succeeded,
					"failed":    summary.Failed,
					"skipped":   summary.Skipped,
					"dry_run":   flags.dryRun,
				}, flags)
			}
			if flags.dryRun {
				fmt.Fprintf(os.Stderr, "Dry run: would create %d issue(s), %d failed, %d skipped (nothing sent)\n", summary.Succeeded, summary.Failed, summary.Skipped)
			} else {
				fmt.Fprintf(os.Stderr, "Import complete: %d succeeded, %d failed, %d skipped\n", summary.Succeeded, summary.Failed, summary.Skipped)
			}
			return nil
		},
	}

	cmd.Flags().StringVarP(&inputFile, "input", "i", "", "Input JSONL file path (use - for stdin)")
	_ = cmd.MarkFlagRequired("input")
	cmd.Flags().IntVar(&batchSize, "batch-size", 1, "Records per batch (future: batch API support)")
	cmd.Flags().StringVar(&dbPath, "db", "", "Database path (for team-key resolution and pp_created ledger)")
	cmd.Flags().StringVar(&session, "session", "", "pp_created session tag for imported issues")

	return cmd
}
